class Solution {
public:
    void duplicateZeros(vector<int>& arr) {
        int n = arr.size(), zeros = 0;
        for (int x : arr) zeros += x == 0;
        for (int i = n - 1, w = n + zeros - 1; i >= 0; i--, w--) {
            if (w < n) arr[w] = arr[i];
            if (arr[i] == 0) {
                w--;
                if (w < n) arr[w] = 0;
            }
        }
    }
};
